CREATE TABLE IF NOT EXISTS "shell"."user_state" (
    "source" text NOT NULL,
    "item_key" text NOT NULL,
    "is_favorite" boolean NOT NULL DEFAULT false,
    "accessed_at_ms" bigint,
    "frequency_score" double precision,
    "favorite_order" double precision,
    "display_name" text,
    "icon" text,
    "updated_at_ms" bigint NOT NULL DEFAULT ((EXTRACT(epoch FROM now()) * (1000)::numeric))::bigint,
    "last_opened_at_ms" bigint,
    CONSTRAINT "user_state_pkey" PRIMARY KEY ("source", "item_key")
);

CREATE TABLE IF NOT EXISTS "spaces"."action_arguments" (
    "action_argument_id" bigint NOT NULL DEFAULT nextval('spaces.action_arguments_action_argument_id_seq'::regclass),
    "invocation_id" text NOT NULL,
    "argument_name" text NOT NULL,
    "scalar_value" text,
    "text_content" text,
    CONSTRAINT "action_arguments_pkey" PRIMARY KEY ("action_argument_id"),
    CONSTRAINT "action_arguments_invocation_id_argument_name_key" UNIQUE ("invocation_id", "argument_name")
);
    -- FOREIGN KEY `action_arguments_invocation_id_fkey`: `invocation_id` → `spaces.action_invocations` (`invocation_id`)

CREATE TABLE IF NOT EXISTS "spaces"."action_invocations" (
    "global_seq" bigint NOT NULL DEFAULT nextval('spaces.action_invocations_global_seq_seq'::regclass),
    "invocation_id" text NOT NULL,
    "space_slug" text NOT NULL,
    "space_display_name" text,
    "action" text NOT NULL,
    "transport" text NOT NULL DEFAULT 'unknown'::text,
    "request_id" text,
    "status" text NOT NULL,
    "invoked_at_text" text,
    "invoked_at_unix_ms" bigint NOT NULL DEFAULT 0,
    "invoked_at" timestamp with time zone NOT NULL,
    "settled_at_text" text,
    "settled_at_unix_ms" bigint,
    "duration_ms" bigint,
    "args_preview" text,
    "result_preview" text,
    "error" text,
    "stream_protocol_messages" bigint,
    "stream_data_messages" bigint,
    "finished_at" timestamp with time zone,
    "source_kind" text,
    "source_ref" text,
    "trigger_ref" text,
    CONSTRAINT "action_invocations_pkey" PRIMARY KEY ("invocation_id"),
    CONSTRAINT "action_invocations_global_seq_key" UNIQUE ("global_seq")
);
    -- FOREIGN KEY `action_invocations_request_id_fkey`: `request_id` → `runtime.requests` (`request_id`)

CREATE TABLE IF NOT EXISTS "spaces"."action_results" (
    "invocation_id" text NOT NULL,
    "result_text" text,
    "error_text" text,
    CONSTRAINT "action_results_pkey" PRIMARY KEY ("invocation_id")
);
    -- FOREIGN KEY `action_results_invocation_id_fkey`: `invocation_id` → `spaces.action_invocations` (`invocation_id`)

CREATE TABLE IF NOT EXISTS "spaces"."backfill_markers" (
    "marker" text NOT NULL,
    "completed_at" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "backfill_markers_pkey" PRIMARY KEY ("marker")
);

CREATE TABLE IF NOT EXISTS "spaces"."file_artifact_identities" (
    "slug" text NOT NULL,
    "artifact_id" uuid NOT NULL DEFAULT gen_random_uuid(),
    "created_at" timestamp with time zone NOT NULL DEFAULT now(),
    CONSTRAINT "file_artifact_identities_pkey" PRIMARY KEY ("slug")
);

CREATE TABLE IF NOT EXISTS "spaces"."proposals" (
    "proposal_id" text NOT NULL,
