    CONSTRAINT "shares_pkey" PRIMARY KEY ("space_slug"),
    CONSTRAINT "shares_shortcode_key" UNIQUE ("shortcode")
);
    -- FOREIGN KEY `shares_space_slug_fkey`: `space_slug` → `spaces.spaces` (`space_slug`)

CREATE TABLE IF NOT EXISTS "spaces"."spaces" (
    "space_slug" text NOT NULL,
    "display_name" text NOT NULL,
    "space_root_path" text,
    "db_path" text,
    "force_order" bigint,
    "session_id" text,
    "construction_status" text,
