    "builder_provenance_lost_build_id" text,
    "builder_provenance_build_id" text,
    "builder_provenance_evidence_jsonl" text,
    CONSTRAINT "spaces_pkey" PRIMARY KEY ("space_slug")
);

CREATE TABLE IF NOT EXISTS "spaces"."user_state" (
    "space_slug" text NOT NULL,
    "is_favorite" boolean NOT NULL DEFAULT false,
    "accessed_at_ms" bigint,
